    negated_conditions: List[str] = []

    for var_name, op, value_str in comparisons:
        try:
            value = float(value_str)
        except ValueError:
            continue

        if var_name not in declared:
            declarations.append(f"(declare-const {var_name} Real)")
            declared.add(var_name)

        smt_op = {">=": ">=", "<=": "<=", ">": ">", "<": "<",
                   "==": "=", "!=": "distinct"}[op]

        if var_name in constants and isinstance(constants[var_name], (int, float)):
            grounded = float(constants[var_name])
            grounding_assert = f"(assert (= {var_name} {grounded}))"
            if grounding_assert not in assertions:
                assertions.append(grounding_assert)
            negated_conditions.append(f"(not ({smt_op} {var_name} {value}))")
            has_grounding = True
        else:
            negated_conditions.append(f"(not ({smt_op} {var_name} {value}))")

    # Negate the conjunction correctly: NOT(A AND B) = (NOT A) OR (NOT B)
    if len(negated_conditions) == 1:
        assertions.append(f"(assert {negated_conditions[0]})")
    elif len(negated_conditions) > 1:
        or_clause = "(or " + " ".join(negated_conditions) + ")"
        assertions.append(f"(assert {or_clause})")
